<script>
import { mapState } from 'vuex'
import api from '@/api/index.js'

export default {
	data() {
		return {
			statistics: {},
			projects: [],
			currentDate: ''
		}
	},
	computed: {
		...mapState(['userInfo']),
		inProgressProjects() {
			return this.projects.filter(p => p.status === 'in_progress').slice(0, 3)
		}
	},
	onLoad() {
		this.loadData()
		this.getCurrentDate()
	},
	onShow() {
		this.loadData()
	},
	methods: {
		getCurrentDate() {
			const now = new Date()
			const month = now.getMonth() + 1
			const day = now.getDate()
			const weekDays = ['周日', '周一', '周二', '周三', '周四', '周五', '周六']
			this.currentDate = `${month}月${day}日 ${weekDays[now.getDay()]}`
		},
		
		async loadData() {
			try {
				const [statsRes, projectsRes] = await Promise.all([
					api.getStatistics(),
					api.getProjects()
				])
				if (statsRes.success) {
					this.statistics = statsRes.data
				}
				if (projectsRes.success) {
					this.projects = projectsRes.data
				}
			} catch (e) {
				console.error(e)
			}
		},
		
		goToPage(url) {
			uni.navigateTo({ url })
		},
		
		goToProjectDetail(id) {
			uni.navigateTo({
				url: '/pages/project/detail?id=' + id
			})
		},
		
		getPriorityText(priority) {
			const map = { high: '高优先级', medium: '中优先级', low: '低优先级' }
			return map[priority] || priority
		}
	}
}
</script>

